<?php
declare(strict_types=1);require dirname(__DIR__).'/workflow-core.php';trackingHeaders();if(($_SERVER['REMOTE_USER']??'')!=='aor-project-admin'){http_response_code(403);exit('Project admin is locked.');}
try{$id=trackingId((string)($_GET['project']??''));$record=workflowProject(trackingRead($id));$type=(string)($_GET['type']??'');$wanted=(string)($_GET['file']??'');$path='';$name='';$mime='application/octet-stream';if(in_array($type,['proposal','delivery'],true)){foreach($record[$type.'_files'] as $file)if(hash_equals($file['id'],$wanted)){$path=workflowFilePath($id,$file,$type);$name=$file['name'];$mime=$file['mime'];}}elseif($type==='invoice'){foreach($record['invoices'] as $invoice)if(hash_equals($invoice['number'],$wanted)){$path=workflowFilesDirectory($id,'invoice').DIRECTORY_SEPARATOR.$invoice['number'].'.pdf';$name=$invoice['number'].'.pdf';$mime='application/pdf';}}if(!$path||!is_file($path))throw new OutOfBoundsException('File unavailable.');header('Content-Type: '.$mime);header('Content-Length: '.filesize($path));header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($name));readfile($path);}catch(Throwable $e){http_response_code(404);echo'File unavailable.';}
